def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the solid separator row or column.
    row_sep = next((i for i, row in enumerate(grid) if len(set(row)) == 1), None)
    if row_sep is not None:
        panels = [grid[:row_sep], grid[row_sep + 1:]]
        # The panel above the separator is the output panel.
        panel = panels[0]
    else:
        col_sep = next(j for j in range(w)
                       if len({grid[i][j] for i in range(h)}) == 1)
        panel = [row[col_sep + 1:] for row in grid]

    return [[0 if v == 0 else 2 for v in row] for row in panel]
