def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_row = next((i for i, row in enumerate(grid)
                    if len(set(row)) == 1), None)

    if sep_row is not None:
        a, b = grid[:sep_row], grid[sep_row + 1:]
        n = min(len(a), len(b))
        return [[2 if a[r][c] != 0 and b[r][c] != 0 else 0
                 for c in range(w)] for r in range(n)]

    sep_col = next(j for j in range(w)
                   if len({grid[i][j] for i in range(h)}) == 1)
    return [[2 if grid[r][c] != 0 and grid[r][c + sep_col + 1] != 0 else 0
             for c in range(sep_col)] for r in range(h)]
