def transform(grid):
    sep = next(i for i, row in enumerate(grid) if len(set(row)) == 1)
    top, bottom = grid[:sep], grid[sep + 1:]
    # In each panel, the most common color is its background.
    def background(panel):
        counts = {}
        for row in panel:
            for v in row:
                counts[v] = counts.get(v, 0) + 1
        return max(counts, key=counts.get)

    bg1, bg2 = background(top), background(bottom)
    return [
        [2 if top[r][c] != bg1 and bottom[r][c] != bg2 else 0
         for c in range(len(grid[0]))]
        for r in range(min(len(top), len(bottom)))
    ]
